#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-05

# strict-mode: opt-out this driver's job is to RUN failing scripts and read their exit codes;
# `set -e` would abort on the first mutation run instead of recording its verdict.
# Mutation gate for the security suite.
#
# Makes "this test cannot fail" a build failure.
#
# 47 of 103 security test functions could not fail and the suite stayed green
# for months because nothing checked. Passing is not evidence: a test only
# counts if a wrong answer would have made it red. This gate proves that, per
# file, by inverting one expectation and demanding the file notice.
#
# HOW IT WORKS
#   Every verdict-bearing security assertion funnels through expect_decision()
#   in tests/fixtures/test-helpers.sh. Running a file with ORK_MUTATE_INDEX=1
#   makes that helper invert the FIRST deny/ask expectation it reaches, print
#   one machine-readable ORK_MUTATION_RESULT line, and exit:
#     exit 0  DETECTED  the flip was caught  -> the assertion bites
#     exit 87 BLIND     the flip passed      -> the assertion is inert
#     exit 88 ERROR     hook unreachable     -> hard failure, never a pass
#   No result line at all means the assertion was never executed (skipped
#   branch, early return, no expect_decision call). That is also a failure.
#
#   No file is edited, so there is no restore step to skip and nothing is left
#   on disk if the run is killed.
#
# NOT named test-*.sh on purpose: scripts/ci/run-tests.sh globs that pattern
# and would pull this driver into the normal suite.
#
# Usage:
#   bash tests/security/mutation-gate.sh
#   bash tests/security/mutation-gate.sh --dir <path>       # self-test a fixture dir
#   bash tests/security/mutation-gate.sh --baseline <n>     # override the ratchet
#
# Exit codes: 0 = at or under baseline, 1 = regression.

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
export CLAUDE_PROJECT_DIR="$PROJECT_ROOT"

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[0;33m'
BOLD='\033[1m'
NC='\033[0m'

# ---------------------------------------------------------------------------
# STATIC_ONLY — files that legitimately never invoke a hook.
# ---------------------------------------------------------------------------
# These grep source, packaging output, or lockfiles rather than feeding a
# payload to a PreToolUse hook, so there is no verdict to invert. Each needs a
# one-line reason. Everything else is a mutation candidate BY DEFAULT, which is
# the point: a new security test must be either mutation-provable or explicitly
# declared static on the day it is written.
declare -A STATIC_ONLY=(
  [test-secret-scanning.sh]="greps the repo for committed secrets; no hook in the loop"
  [test-packaging-leaks.sh]="inspects the built plugin payload on disk"
  [test-npm-audit.sh]="shells out to npm audit and reads its JSON"
  [test-npm-audit-coverage.sh]="asserts every workspace is covered by an audit job"
  [test-dependency-confusion.sh]="reads package.json/lockfile registry pins"
  [test-mcp-deny-case.sh]="asserts deny-rule casing in settings JSON, not a runtime verdict"
  [test-json-island-breakout.sh]="static scan of workflow YAML for JSON-island script breakout"
)

# ---------------------------------------------------------------------------
# MUTATION_BASELINE — ratchet, in the style of
# tests/skills/structure/test-test-discovery.mjs.
# ---------------------------------------------------------------------------
# Number of candidate files that are NOT mutation-provable today. It may fall,
# never rise. A new security test lands as a candidate, so shipping one that
# cannot fail pushes this over the line and breaks the build.
# 2026-08-05: test-jq-injection.sh and test-sqlite-injection.sh reach no
# verdict-bearing assertion. Lower this the moment they do.
MUTATION_BASELINE=2

TARGET_DIR="$SCRIPT_DIR"
MAX_JOBS=8

while [[ $# -gt 0 ]]; do
  case "$1" in
    --dir) TARGET_DIR="$(cd "$2" && pwd)"; shift 2 ;;
    --baseline) MUTATION_BASELINE="$2"; shift 2 ;;
    --jobs) MAX_JOBS="$2"; shift 2 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

# ---------------------------------------------------------------------------
# Candidate discovery
# ---------------------------------------------------------------------------
shopt -s nullglob
ALL_TESTS=("$TARGET_DIR"/test-*.sh)
shopt -u nullglob

if [[ ${#ALL_TESTS[@]} -eq 0 ]]; then
  echo -e "${RED}No test-*.sh files found in $TARGET_DIR — refusing to report success${NC}"
  exit 1
fi

CANDIDATES=()
SKIPPED=()
for f in $(printf '%s\n' "${ALL_TESTS[@]}" | sort); do
  base="$(basename "$f")"
  if [[ -n "${STATIC_ONLY[$base]:-}" ]]; then
    SKIPPED+=("$base")
  else
    CANDIDATES+=("$f")
  fi
done

RESULT_DIR="$(mktemp -d -t ork-mutate-XXXXXX)"
trap 'rm -rf "$RESULT_DIR"' EXIT

# ---------------------------------------------------------------------------
# One mutation run per file, in parallel (mirrors bin/git-hooks/pre-push:297).
# ---------------------------------------------------------------------------
export RESULT_DIR CLAUDE_PROJECT_DIR

_mutate_one() {
  local file="$1"
  local base out code line verdict
  base="$(basename "$file")"

  out="$(ORK_MUTATE_INDEX=1 bash "$file" 2>&1)"
  code=$?

  # grep -a: test-unicode-attacks.sh contains bytes that make grep treat the
  # stream as binary, and plain grep then silently prints nothing.
  line="$(printf '%s\n' "$out" | grep -a '^ORK_MUTATION_RESULT ' | head -1)"

  if [[ -z "$line" ]]; then
    # The assertion never ran: skipped branch, early return, or no
    # verdict-bearing expect_decision call at all.
    printf 'NO_ASSERTION|%s|no ORK_MUTATION_RESULT line (exit %s)\n' "$base" "$code" \
      > "$RESULT_DIR/$base"
    return 0
  fi

  verdict="$(printf '%s\n' "$line" | sed -n 's/.*verdict=\([A-Z_]*\).*/\1/p')"

  # -------------------------------------------------------------------------
  # Probe B: does the FILE propagate the failure?
  #
  # Probe A above proves the ASSERTION bites, and stops there — it exits from
  # inside expect_decision, so the file's own `[[ $FAIL -eq 0 ]]` line never
  # runs. That leaves a hole: a file that detects the flip and then discards it
  # (`expect_decision ... || true`, or a trailing unconditional `exit 0`) scored
  # CAN FAIL while being incapable of failing. Confirmed with a planted probe.
  # Swallowed exit codes are one of the three root causes of the original 47
  # no-op functions, so the gate has to see them.
  #
  # ORK_MUTATE_NOEXIT adopts the inverted expectation and lets the file finish.
  # The assertion must then be red AND the file must exit non-zero.
  if [[ "$verdict" == "DETECTED" ]]; then
    local bcode
    ORK_MUTATE_INDEX=1 ORK_MUTATE_NOEXIT=1 bash "$file" >/dev/null 2>&1
    bcode=$?
    if (( bcode == 0 )); then
      printf 'SWALLOWED|%s|assertion bites but the file still exits 0 (gate discarded or missing)\n' \
        "$base" > "$RESULT_DIR/$base"
      return 0
    fi
  fi

  printf '%s|%s|%s\n' "$verdict" "$base" "$line" > "$RESULT_DIR/$base"
}
export -f _mutate_one

printf '%s\n' "${CANDIDATES[@]}" | xargs -P "$MAX_JOBS" -I {} bash -c '_mutate_one "$1"' _ {}

# ---------------------------------------------------------------------------
# Report
# ---------------------------------------------------------------------------
echo ""
echo -e "${BOLD}Security Mutation Gate — can these tests fail?${NC}"
echo "============================================================================"
echo ""

DETECTED=0
NOT_PROVABLE=()

for base in $(ls "$RESULT_DIR" | sort); do
  IFS='|' read -r verdict name detail < "$RESULT_DIR/$base"
  case "$verdict" in
    DETECTED)
      DETECTED=$((DETECTED + 1))
      echo -e "  ${GREEN}CAN FAIL${NC}     : $name"
      ;;
    BLIND)
      NOT_PROVABLE+=("$name")
      echo -e "  ${RED}BLIND${NC}        : $name"
      echo "                 $detail"
      ;;
    ERROR)
      NOT_PROVABLE+=("$name")
      echo -e "  ${RED}HOOK ERROR${NC}   : $name (hook unreachable — never a pass)"
      echo "                 $detail"
      ;;
    SWALLOWED)
      NOT_PROVABLE+=("$name")
      echo -e "  ${RED}SWALLOWED${NC}    : $name (assertion bites, file still exits 0)"
      echo "                 $detail"
      ;;
    *)
      NOT_PROVABLE+=("$name")
      echo -e "  ${RED}NO ASSERTION${NC} : $name"
      echo "                 $detail"
      ;;
  esac
done

for base in "${SKIPPED[@]}"; do
  echo -e "  ${YELLOW}STATIC${NC}       : $base — ${STATIC_ONLY[$base]}"
done

FAILED=${#NOT_PROVABLE[@]}

echo ""
echo "============================================================================"
echo -e "  candidates      : ${#CANDIDATES[@]}  (static-only: ${#SKIPPED[@]})"
echo -e "  proven CAN FAIL : $DETECTED"
echo -e "  NOT provable    : $FAILED / $MUTATION_BASELINE baseline"

if (( FAILED > MUTATION_BASELINE )); then
  echo ""
  echo -e "  ${RED}${BOLD}== REGRESSION ($FAILED > $MUTATION_BASELINE) ==${NC}"
  echo "  These security tests cannot fail. A wrong answer from the hook would"
  echo "  not turn them red, so they are decoration, not a gate. Either wire the"
  echo "  assertion to a live hook via expect_decision, or — if the file"
  echo "  legitimately greps source instead of invoking a hook — add it to"
  echo "  STATIC_ONLY in mutation-gate.sh with a reason."
  for n in "${NOT_PROVABLE[@]}"; do echo "     $n"; done
  echo ""
  echo -e "  ${RED}${BOLD}FAILED${NC}: non-provable security tests rose to $FAILED"
  echo "============================================================================"
  exit 1
fi

if (( FAILED < MUTATION_BASELINE )); then
  echo ""
  echo -e "  ${YELLOW}NOTE${NC}: non-provable count fell to $FAILED. Lower MUTATION_BASELINE"
  echo "        to $FAILED to lock the gain in."
fi

echo ""
echo -e "  ${GREEN}${BOLD}OK${NC}: non-provable held at $FAILED (baseline $MUTATION_BASELINE)"
echo "============================================================================"
exit 0
